'use strict';
const DagobahCardRules=(()=>{
 const cards=[{"id":"Light:30","name":"A Jedi's Strength","type":"Jedi Test #2","text":"Deploy on an unoccupied Dagobah site. At the beginning of each of your move phases, opponent may relocate this Jedi Test to an adjacent site. Target a mentor on Dagobah and an apprentice who has completed Jedi Test #1. Apprentice may move only by using personal landspeed. Attempt when apprentice is present at the beginning of your control phase. Draw training destiny. If destiny + apprentice's ability > 13, test completed: Place on apprentice. Apprentice is power +1 and may move normally. Total ability of 6 or more is required for opponent to draw battle destiny."},{"id":"Light:111","name":"•Anger, Fear, Aggression","type":"Effect","text":"Insert in opponent's Reserve Deck. When Effect reaches top it is lost, but opponent must initiate a battle by the end of opponent's next battle phase or lose 4 Force. (Immune to Alter.)"},{"id":"Light:113","name":"•Anoat","type":"Location","text":"Light: If opponent initiates a battle here, your starships may move as a 'react' to or from nearest related asteroid sector. Dark: Your Ugnaughts deploy free aboard starships here. If you control, all your Ugnaughts on table are forfeit +2."},{"id":"Light:149","name":"<><><>Asteroid Field","type":"Location","text":"Light: 'Asteroid Rules' in effect here. If you control, may cancel Force drain at related system. Dark: 'Asteroid Rules' in effect here."},{"id":"Light:150","name":"<>Asteroid Sanctuary","type":"Effect","text":"Deploy on any asteroid sector you control. During each of your control phases, opponent loses X Force, where X = total number of asteroid sectors at same system that are not occupied by opponent. Effect canceled if opponent controls this location."},{"id":"Light:151","name":"•Asteroids Do Not Concern Me","type":"Effect","text":"Deploy on any asteroid sector. Target one opponent's capital starship. Pilots aboard target may not use ability to draw battle destiny. Subtract 4 from asteroid destiny when targeting that starship. Utinni Effect canceled when reached by target."},{"id":"Light:155","name":"Astromech Translator","type":"Device","text":"Deploy on any starfighter. While an astromech character is aboard: If not piloted, starfighter may move and may use power, maneuver and hyperspeed. OR if piloted, starfighter is immune to attrition < 3 (< 6 if matching pilot aboard)."},{"id":"Light:157","name":"•At Peace","type":"Effect","text":"Deploy on any apprentice at the beginning of your turn. Apprentice 'rests' (may not attempt Jedi Tests) until end of your next turn, then relocate Immediate Effect to Jedi Test. When attempting this test, that apprentice adds 3 to training destiny. (Immune to Control.)"},{"id":"Light:177","name":"•Away Put Your Weapon","type":"Interrupt","text":"USED: If a lightsaber was just used to enhance a Force drain, place it in Owner's Used Pile. LOST: Place any or all of your devices and character weapons on table in your Used Pile."},{"id":"Light:236","name":"<>Big One","type":"Location","text":"Light: 'Asteroid Rules' in effect here. If you control, Force drain +1 here for each Asteroid Field at same system. Dark: 'Asteroid Rules' in effect here. If you control, Force drain +1 here."},{"id":"Light:238","name":"<>Big One: Asteroid Cave Or Space Slug Belly","type":"Location","text":"Light: 'Cave Rules' in effect here. If you control, may cancel Force drains at system Related to Big One. Dark: 'Cave Rules' in effect here."},{"id":"Light:258","name":"•Blasted Varmints","type":"Interrupt","text":"Use 1 Force to cause all Mynocks or Vine Snakes to detach from one starfighter or character. OR Cause one Mynock attached to any starfighter to be lost. OR After creature has selected a target character, cancel that selection and select again."},{"id":"Light:297","name":"Bog-wing","type":"Creature","text":"* Ferocity = destiny -1. Habitat: Dagobah. Parasite: Character (that can move). Relocate Bog-wing and host up to two sites away (opponent of victim chooses). Bog-wing then detaches."},{"id":"Light:424","name":"•Closer?!","type":"Interrupt","text":"During your move phase, use 1 Force to relocate one of your starships from a planet system to any related asteroid sector (or vice versa). This movement is free if a smuggler is on board. OR Cancel Rogue Asteroid or Close Call."},{"id":"Light:521","name":"Control","type":"Interrupt","text":"Cancel one Sense or Alter card. (Immune to Sense.) OR Cancel one Immediate Effect, Mobile Effect or Force drain."},{"id":"Light:597","name":"•Dagobah","type":"Location","text":"Light: During your deploy phase, you may deploy one Dagobah site directly from Reserve Deck. Shuffle, cut and replace. Dark: Neither player may Force drain here."},{"id":"Light:598","name":"•Dagobah: Bog Clearing","type":"Location","text":"Light: Your starfighters may deploy here and are immune to Awwww, Cannot Get Your Ship Out here. Dark: If you occupy, Force generation +1 for you here."},{"id":"Light:600","name":"•Dagobah: Jungle","type":"Location","text":"Light: No starships or vehicles here. Your creatures are deploy -2 here. Dark: No starships or vehicles here. If you occupy, Force generation +1 for you here."},{"id":"Light:601","name":"•Dagobah: Swamp","type":"Location","text":"Light: At end of your turn, your starships and vehicles here 'sink' to Used Pile. Dark: At end of your turn, your starships and vehicles here 'sink' to bottom of Lost Pile."},{"id":"Light:602","name":"•Dagobah: Training Area","type":"Location","text":"Light: Once per turn, may search Reserve Deck. Take one Jedi Test into hand. Reshuffle deck. Dark: You may use 1 Force to cancel any Force drain here."},{"id":"Light:603","name":"•Dagobah: Yoda's Hut","type":"Location","text":"Light: If Yoda here, once per turn, may subtract 2 from attrition against you at another location. Dark: If you occupy, opponent's Yoda's Hut game text is canceled."},{"id":"Light:708","name":"•Descent Into The Dark","type":"Effect","text":"During your turn, if either player just placed a card in a Used Pile, deploy on table. All Used Piles are immediately re-circulated. When any player places one or more cards in a Used Pile, Immediate Effect canceled."},{"id":"Light:745","name":"•Do, Or Do Not","type":"Effect","text":"Deploy on table. Sense and Alter are now Lost Interrupts. Also, when and player makes a destiny draw for Sense or Alter, and that destiny draw is successful, that player loses 2 Force. (Immune to Alter.)"},{"id":"Light:752","name":"Domain Of Evil","type":"Jedi Test #3","text":"Deploy on Dagobah: Jungle or Dagobah: Cave. Target a mentor on Dagobah and an apprentice who has completed Jedi Test #2. Attempt when apprentice is present at the end of your turn and none of your cards participated in battles, Force drains or Jedi Tests during that turn. Draw training destiny. If destiny + apprentice's ability > 14, test completed. Place on apprentice. You may subtract 1 from each of opponent's destiny draws."},{"id":"Light:780","name":"Droid Sensorscope","type":"Device","text":"Deploy on one of your R-unit droids. During any control phase, you may use 1 Force to peek at the top card of opponent's Reserve Deck. Also, if on Dagobah, droid may move for free."},{"id":"Light:814","name":"Effective Repairs","type":"Interrupt","text":"USED: Cancel Limited Resources. LOST: Use 3 Force to retrieve into hand one Effect of any kind."},{"id":"Light:817","name":"•Egregious Pilot Error","type":"Interrupt","text":"During opponent's control phase, if opponent has two or more capital starships at a system or sector together, draw destiny. If destiny -1 < number of those starships, they may not move or participate in battle until end of your next turn."},{"id":"Light:838","name":"<>Encampment","type":"Effect","text":"Use 2 Force to deploy on any exterior planet site where you have a Rebel or alien. You may deploy characters at this site, even without presence, regardless of location deployment restrictions."},{"id":"Light:957","name":"•Flash Of Insight","type":"Effect","text":"Deploy on your side of table. At any time, you may use 3 Force to draw the top card of your Reserve Deck into your hand. If that card is a space creature, you may immediately deploy it for free."},{"id":"Light:976","name":"Found Someone You Have","type":"Interrupt","text":"If you have a character of ability > 4 on table, use 3 Force to find one of your missing characters (your choice). OR During any control phase, examine the top card of your Lost Pile. If that card is a character of ability < 3, take that character into hand."},{"id":"Light:1071","name":"Great Warrior","type":"Jedi Test #1","text":"Deploy on a Dagobah site. Target a mentor here. Also, target or deploy (regardless of location deployment restrictions) an apprentice here. Attempt when targets are present at the beginning of your control phase. Draw training destiny. If destiny + apprentice's ability > 12, test completed: Place on apprentice. All opponent's Force drain bonuses are canceled. Mentor: Your character of ability > 2. Apprentice: Your non-droid, non-Jedi character of lesser ability than mentor. Each time you complete any Jedi Test, you may exchange one card in hand for one Jedi Test in your Lost Pile."},{"id":"Light:1084","name":"Grounded Starfighter","type":"Effect","text":"Deploy on a landed starship (not at a docking bay). Starship may not move. OR Deploy on a starship or vehicle on Dagobah. Starship or vehicle may not move. At the start of your next control phase, starship or vehicle 'sinks' to bottom of the Lost Pile."},{"id":"Light:1108","name":"•Han's Toolkit","type":"Device","text":"Use 1 Force to deploy on one of your characters, vehicles or starships (free on Falcon or Han). While aboard a vehicle or starship, you may use 1 Force to cancel any Interrupt or Effect of any kind (except those immune to Alter or Control) which targets that vehicle or starship."},{"id":"Light:1140","name":"•Hiding In The Garbage","type":"Effect","text":"Use 2 Force to deploy on your side of table. At any time, you may declare a card type. Use Force one by one, revealing each card used, until a card of that type is revealed (take it into hand) or Force Pile is depleted."},{"id":"Light:1212","name":"I Have A Bad Feeling About This","type":"Interrupt","text":"Use 3 Force: Retarget an Interrupt or Utinni Effect which specifies a target to another appropriate target on the same side of the Force. OR Relocate any Effect (except those immune to Alter) deployed on a location to another appropriate location."},{"id":"Light:1303","name":"Ineffective Maneuver","type":"Effect","text":"Deploy on any Effect or Utinni Effect (except those immune to Alter). During each of owner's draw phases, if you occupy an asteroid sector, owner must choose to either lose 1 Force or voluntarily cancel that Effect or Utinni Effect. (Immune to Alter.)"},{"id":"Light:1332","name":"It Is The Future You See","type":"Jedi Test #5","text":"Deploy on a Dagobah site. Target a mentor on Dagobah and an apprentice who has completed Jedi Test #4. Attempt when apprentice is present at the beginning of your control phase. Turn apprentice upside down (cannot move and power = 0). At the end of your next turn, turn apprentice right side up (restored): Place on apprentice. Immune to attrition < 4. Reveal the top two cards of your Reserve Deck and place one upside down on apprentice. Whenever you are about to draw a card for destiny, you may instead use the upside-down card (which remains on apprentice for re-use)."},{"id":"Light:1384","name":"Jedi Levitation","type":"Interrupt","text":"Use X force, where X = (7 - ability of your highest ability character on table). Search through your Used Pile and take one card into hand. Shuffle, Cut and replace."},{"id":"Light:1464","name":"••Landing Claw","type":"Device","text":"Deploy on one of your starfighters. During any control phase, may target one opponent's capital starship present. Starfighter attaches to target (automatically moves with target and is 'concealed'). May detach at any time (even as target begins to move)."},{"id":"Light:1512","name":"Levitation","type":"Interrupt","text":"USED: Cancel Silence Is Golden or Shut Him Up Or Shut Him Down. LOST: Search your Used Pile and take any one droid, device or Stone Pile you find there into hand. Shuffle, cut and replace."},{"id":"Light:1550","name":"Light Maneuvers","type":"Interrupt","text":"Cancel Dark Maneuvers, Emergency Deployment, Lone Pilot, I Want That Ship, Defensive Fire, Rogue Asteroid or Take Evasive Action. OR Double Special Modifications until end of turn."},{"id":"Light:1585","name":"Lost Relay","type":"Interrupt","text":"Target one opponent's starfighter present with one of your starships at an asteroid sector, before asteroid destiny is drawn this turn. If target lost this turn due to asteroid destiny, opponent also loses Force equal to target's forfeit value."},{"id":"Light:1602","name":"•Luke's Backpack","type":"Device","text":"Deploy on any character. May carry and use any number of devices. May also carry Yoda, Kabe or any one Jawa or Ewok (as if riding a creature vehicle). Adds 1 to training destiny when carrying the Mentor."},{"id":"Light:1708","name":"•Moving To Attack Position","type":"Interrupt","text":"Target one starfighter participating in a battle at a system or sector. For remainder of turn, starfighter may not move, is immune to attrition and, if piloted by any Corellian, is power +2."},{"id":"Light:1719","name":"Mynock","type":"Creature","text":"Habitat: unlimited. Parasite: Starfighter. Host's power and hyperspeed are cumulatively -2; while both < 1, Mynocks randomly detach one at a time (cannot attach for remainder of turn). Moves like a starfighter."},{"id":"Light:1768","name":"•Never Tell Me The Odds","type":"Effect","text":"Insert in opponent's Reserve Deck. When Effect reaches top it is lost and up to the three lowest destiny numbers of each player's characters on table are totaled. Player with lower total loses Force equal to the difference. (Immune to Alter.)"},{"id":"Light:1785","name":"•No Disintegrations!","type":"Effect","text":"Use 2 Force to deploy on your side of table. If a Rebel of ability > 2 is lost (not captured) during a battle involving an opponent's bounty hunter, opponent loses 3 Force. If Vader on table, one bounty hunter involved in that battle (your choice) is also lost."},{"id":"Light:1799","name":"Nudj","type":"Creature","text":"*Ferocity = destiny - 4. Habitat: planet sites (except Hoth and Tatooine) and Dark Waters. Cumulatively absorbs (temporarily cancels) one [Dark Side Force] icon present. Parasite: None."},{"id":"Light:1808","name":"•Obi-Wan's Apparition","type":"Effect","text":"Use 4 Force to deploy on any site if opponent is generating at least 3 Force more than you. At that site, adjacent sites and same sites as Obi-Wan, players activate Force only if they have presence."},{"id":"Light:1856","name":"•Order To Engage","type":"Effect","text":"Use 2 Force to deploy on opponent's side of table. At the end of each of opponent's battle phases, if a battle did not take place at every location where both players have presence at the end of that phase, opponent loses 3 Force."},{"id":"Light:1920","name":"Polarized Negative Power Coupling","type":"Effect","text":"Deploy on table. Turn every Used Pile face up. All subsequent cards placed in Used Piles are also turned face up. (Players must commit to using cards before revealing them.) Turn used cards face down whenever they are re-circulated."},{"id":"Light:1926","name":"Portable Fusion Generator","type":"Device","text":"Deploy on any warrior. When that warrior fires a blaster rifle or artillery weapon, adds 1 to each of that weapon's destiny draws. Also, may add 1 to power of one droid present."},{"id":"Light:1976","name":"Quick Draw","type":"Effect","text":"Deploy on your side of table. Once during each of your draw phases, you may use 2 Force to search your Lost Pile. Take any one blaster you find there and immediately deploy it (for free)."},{"id":"Light:2014","name":"•Raithal","type":"Location","text":"Light: If you control, all opponent's troopers are forfeit and destiny -1. Dark: If you control, you may raise your converted Raithal system to the top."},{"id":"Light:2037","name":"Rebel Flight Suit","type":"Device","text":"Deploy on your pilot character. While piloting any starfighter, combat vehicle or shuttle vehicle, that character is considered to be the 'matching pilot' (pilot adds 2 to maneuver (limit +2) and draws one battle destiny if not able to otherwise)."},{"id":"Light:2055","name":"Recoil In Fear","type":"Interrupt","text":"Use 3 Force. Each player places hand onto Reserve Deck (if possible), then places Used Pile onto Reserve Deck; reshuffle. Each player then draws cards from Reserve Deck equal to the number of cards just placed from hand onto Reserve Deck (if any)."},{"id":"Light:2078","name":"•Reflection","type":"Effect","text":"Deploy on Leia. Once during each of your control phases, you may use 3 Force to retrieve 1 Force. Also, when an apprentice, adds 1 to her training destiny."},{"id":"Light:2089","name":"•Report To Lord Vader","type":"Effect","text":"If you just won a battle, deploy on Vader. Target an Imperial involved in that battle. Vader and target are power and forfeit -4. When target reaches Vader, lose Utinni Effect and draw destiny. If destiny > 2, target lost."},{"id":"Light:2104","name":"Retractable Arm","type":"Device","text":"Deploy on any R-unit droid to give that droid thief skill. Once during each of your control phases, you may use 1 Force to target a weapon or device present. Draw destiny. If destiny > 2, target is 'stolen.' Target may then be transferred for free. Droid may not be Disarmed."},{"id":"Light:2124","name":"<>Rogue Asteroid","type":"Effect","text":"Deploy on an asteroid sector and specify starting direction. Every move phase, moves to next adjacent asteroid sector (reversing direction as necessary). Where present, adds 2 to asteroid destiny. May be targeted by starship weapons (defense value = 3)."},{"id":"Light:2143","name":"•Rycar's Run","type":"Effect","text":"Deploy on a Big One. X = twice the number of asteroid sectors at that system. Target a starfighter at related planet system. When reached by target, relocate Utinni Effect to planet system. When target returns to system, lose Utinni Effect. Retrieve X Force."},{"id":"Light:2184","name":"•Scramble","type":"Effect","text":"Deploy on opponent's side of table. Opponent's pilots (except Vader) present at sites may not use ability to draw battle destiny. Effect canceled when opponent has no pilots at sites."},{"id":"Light:2257","name":"•Shoo! Shoo!","type":"Interrupt","text":"If you have a droid on table: Cancel an attack just initiated by a creature. OR Immediately move one opponent's creature (except an attached creature) to an adjacent location (habitat permitting)."},{"id":"Light:2272","name":"Size Matters Not","type":"Jedi Test #4","text":"Deploy on Dagobah: Swamp or Dagobah: Bog Clearing. Target a mentor on Dagobah and an apprentice who has completed Jedi Test #3. Attempt when apprentice is present at the beginning of your control phase. Draw training destiny. If destiny + apprentice's ability > 15, test completed: Place on apprentice. Immune to attrition < 3. Once during each of your control phases, you may use 2 Force to search your Reserve Deck and take any one card you find there into hand. Shuffle, cut and replace."},{"id":"Light:2286","name":"•Smuggler's Blues","type":"Effect","text":"Deploy on a smuggler. May use 2 Force to cancel Limited Resources. Also, if 'trained' by Rycar Ryjerd and piloting a starship when that starship completes Kessel Run, Rycar's Run or The First Transport Is Away, any retrieved Force may be taken into hand."},{"id":"Light:2304","name":"•Son Of Skywalker","type":"Character","text":"Deploys only on Dagobah or Cloud City. Adds 2 to power of anything he pilots. Once per game, during your deploy phase, a lightsaber may deploy on Luke (for free) from Reserve Deck; reshuffle. Immune to attrition < 4."},{"id":"Light:2313","name":"<>Space Slug","type":"Creature","text":"* Ferocity = two destiny. Habitat: Big One (Cave is now Belly). Attacks starfighters (defeated cards are eaten or relocated to Belly, opponent of victim chooses). Once per turn, may open or close mouth."},{"id":"Light:2344","name":"Starship Levitation","type":"Interrupt","text":"USED: Cancel Awwww, Cannot Get Your Ship Out. LOST: Use 1 Force to draw destiny. If destiny < ability of your highest-ability character on table, search your Used Pile and take one starship into hand. Shuffle, cut and replace."},{"id":"Light:2352","name":"••Stone Pile","type":"Effect","text":"Use 2 Force to deploy on any Dagobah site. Randomly select two cards from opponent's hand and place them, unseen, face down beneath Stone Pile. Cards return to opponent's hand if Effect leaves table. Canceled if opponent occupies this site."},{"id":"Light:2539","name":"•The Professor","type":"Effect","text":"Use 3 Force to deploy on your side of the table (free if C-3PO on table). If you have a protocol droid aboard a starship or vehicle in a battle, you may use X Force to reduce the battle damage against you by X (by X + 1 if a Nav Computer character is also aboard)."},{"id":"Light:2561","name":"•They'd Be Crazy To Follow Us","type":"Interrupt","text":"Use 1 Force to target a starship at an asteroid sector or a 'blown away' system. For remainder of turn, you may add 2 to destiny totals targeting the armor or maneuver of that starship."},{"id":"Light:2573","name":"This Is More Like It","type":"Interrupt","text":"During a battle, lose X Force to reduce attrition against you by X. OR Cancel This Is Just Wrong."},{"id":"Light:2574","name":"This Is No Cave","type":"Interrupt","text":"Relocate one starfighter from a Big One to the related site (or vice versa) for free (opens Slug's mouth if closed). If smuggler aboard, starfighter is immune to attrition and subtracts 5 from asteroid destiny until end of your next turn. OR Cancel Corrosive Damage."},{"id":"Light:2585","name":"Through The Force Things You Will See","type":"Interrupt","text":"At the end of any player's draw phase, cause that player to place Used Pile face up on top of Reserve Deck. Shuffle, cut, and replace. When face-up cards are removed from Reserve Deck, they are treated as normal (no longer remain face up)."},{"id":"Light:2605","name":"•Tight Squeeze","type":"Interrupt","text":"If you have a lone vehicle or starfighter in a battle or Attack Run at Beggar's Canyon, Cloud City, Death Star: Trench or an asteroid sector, use 1 Force. At the end of that battle or Attack Run, opponent must forfeit two participating vehicles or starfighters."},{"id":"Light:2629","name":"Transmission Terminated","type":"Interrupt","text":"Cancel one hologram. OR Use 3 Force. Draw destiny. Add 1 to destiny for each asteroid sector on table. If total destiny > 3, Imperial Holotable site is 'blown away' (opponent loses 4 Force)."},{"id":"Light:2643","name":"Tunnel Vision","type":"Interrupt","text":"Search your Force Pile and take one card into hand. Shuffle, cut and replace."},{"id":"Light:2718","name":"Vine Snake","type":"Creature","text":"Habitat: planet sites (except Hoth). Parasite: Non-droid Character. Each move phase, draw destiny; each time destiny > ability, add 1 to X (X starts at 0). Host is power -X (eaten if power = 0)."},{"id":"Light:2722","name":"••Visored Vision","type":"Interrupt","text":"Name an Interrupt card. Opponent must reveal entire Used Pile, without shuffling. Then you choose:USED: Opponent must lose 1 Force for each copy of that Interrupt found there. LOST: Each copy of that interrupt found there is lost."},{"id":"Light:2741","name":"•Wars Not Make One Great","type":"Effect","text":"Deploy on any location. For either player to initiate a battle or Force drain anywhere, that player must use +1 Force. Effect canceled if opponent controls this location."},{"id":"Light:2749","name":"•We Can Still Outmaneuver Them","type":"Interrupt","text":"USED: Search your Reserve Deck. Take one Collision! or Egregious Pilot Error into hand. Shuffle, cut and replace. LOST: If opponent just initiated a battle with at least two capital starships at a system where you have a lone starfighter, add two battle destiny."},{"id":"Light:2752","name":"We Don't Need Their Scum","type":"Interrupt","text":"USED: Cancel Res Luk Ra'auf. LOST: If two bounty hunters (or an Imperial and a bounty hunter) are in a battle together, use 2 Force to draw two destiny. Subtract total from opponent's attrition and total power (cannot fall below zero)."},{"id":"Light:2799","name":"•WHAAAAAAAAAOOOOW!","type":"Interrupt","text":"If one of your characters was just defeated by a Dragonsnake, Rancor, Sarlacc, Dianoga or Wampa, instead of being 'eaten' that character is 'hurled' (relocated) to an adjacent site, if possible."},{"id":"Light:2800","name":"•What Is Thy Bidding, My Master?","type":"Effect","text":"Deploy on Emperor or any system. Target one character whose lore uses the word 'Emperor.' Target cannot use ability to draw battle destiny and is excluded from being the 'highest-ability character.' Utinni Effect canceled when reached by target."},{"id":"Light:2865","name":"•Yoda","type":"Character","text":"Deploy on Dagobah I must, but move elsewhere I may, yes. When the mentor, 1 to training destiny I add. Where present am I, battles and attacks happen not unless present a Dark Side character of ability > 3 there is. To attrition, immune am I."},{"id":"Light:2867","name":"•Yoda Stew","type":"Interrupt","text":"During opponent's turn, take up to four cards from your hand and place them on top of your Force Pile."},{"id":"Light:2871","name":"•Yoda, You Seek Yoda","type":"Interrupt","text":"If Yoda is lost, use 1 Force to retrieve him from the Lost Pile. OR Use 3 Force to search through your Reserve Deck and take Yoda into your hand. Shuffle, cut and replace."},{"id":"Light:2872","name":"•Yoda's Gimer Stick","type":"Effect","text":"Deploy on Yoda. You may initiate battles and attacks where present. OR Use 2 Force to deploy on one of your characters of ability > 3. Immune to attrition. Where present, no battles or attacks may be initiated unless an opponent's character of ability > 3 present."},{"id":"Light:2873","name":"•Yoda's Hope","type":"Effect","text":"Deploy on a character. When on the mentor, adds 1 to training destiny draws. If on Yoda, you may lose Effect to search your Reserve Deck and take into hand one card with 'levitation' in the title. Shuffle, cut and replace."},{"id":"Light:2880","name":"•You Do Have Your Moments","type":"Interrupt","text":"At the start of the damage segment during a battle, before any cards have been forfeited, cause all attrition for both sides to be reduced to zero."},{"id":"Dark:4","name":"•3,720 To 1","type":"Effect","text":"Insert in opponent's Reserve Deck. When Effect reaches top it is lost and up to the three lowest destiny numbers of each player's characters on table are totaled. Player with lower total loses Force equal to the difference. (Immune to Alter.)"},{"id":"Dark:9","name":"•4-LOM","type":"Character","text":"Total power at same site is +1 for each of your alien/droid pairs present. Once during each battle, if present with Zuckuss, may use 1 Force to search any Used Pile and move 1 character there to the Lost Pile. May initiate battle and be battled."},{"id":"Dark:11","name":"•4-LOM's Concussion Rifle","type":"Weapon","text":"Use 4 Force to deploy on your warrior, free on 4-LOM. May target a character or creature for free at same site or exterior site up to 2 sites away. Draw destiny. Add 1 if Blaster Scope attached. If total destiny - distance to target > defense value, target hit."},{"id":"Dark:17","name":"•A Dangerous Time","type":"Interrupt","text":"USED: Examine the cards in opponent's Force Pile. Reorder however you wish and replace. LOST: Search your Reserve Deck and take one Dark Forces into hand. Shuffle, cut and replace."},{"id":"Dark:112","name":"•Anoat","type":"Location","text":"Dark: If opponent initiates a battle here, your starships may move as a 'react' to or from nearest related asteroid sector. Light: If you control, all opponent's Ugnaughts on table are forfeit -1."},{"id":"Dark:121","name":"•Apology Accepted","type":"Interrupt","text":"At the end of any battle phase, lose one of your Imperials of ability < 6 who survived a battle you lost this turn. Activate Force up to either that character's forfeit value or the amount of your battle damage in that battle."},{"id":"Dark:148","name":"<><><>Asteroid Field","type":"Location","text":"Dark: 'Asteroid Rules' in effect here. If you control, may cancel Force drain at related system. Light: 'Asteroid Rules' in effect here."},{"id":"Dark:176","name":"•Avenger","type":"Starship","text":"May add 6 pilots, 8 passengers, 2 vehicles, and 4 TIEs. Has ship-docking capability. Permanent pilot aboard provides ability of 2. Subtract 2 from asteroid destiny draws targeting Avenger."},{"id":"Dark:181","name":"Awwww, Cannot Get Your Ship Out","type":"Effect","text":"Deploy on a landed starship (not at a docking bay). Starship may not move. OR Deploy on a starship or vehicle on Dagobah. Starship or vehicle may not move. At the start of you next control phase, starship or vehicle 'sinks' to the Used Pile."},{"id":"Dark:185","name":"•Bad Feeling Have I","type":"Effect","text":"Deploy on opponent's side of table. Luke, Leia, Han, Chewie, Lando, Yoda, and Obi-Wan are deploy +2. Also, opponent may not play any cards with the words 'bad feeling' in the title."},{"id":"Dark:235","name":"<>Big One","type":"Location","text":"Dark: 'Asteroid Rules' in effect here. If you control, Force drain +1 here for each Asteroid Field at same system. Light: 'Asteroid Rules' in effect here."},{"id":"Dark:237","name":"<>Big One: Asteroid Cave Or Space Slug Belly","type":"Location","text":"Dark: 'Cave Rules' in effect here. If you control, may cancel Force drains at system related to Big One. Light: 'Cave Rules' in effect here."},{"id":"Dark:296","name":"Bog-wing","type":"Creature","text":"* Ferocity = destiny -1. Habitat: Dagobah. Parasite: Character (that can move). Relocate Bog-wing and host up to two sites away (opponent of victim chooses). Bog-wing then detaches."},{"id":"Dark:299","name":"<>Bombing Run","type":"Effect","text":"Deploy on a non-interior planet site (except Dagobah). May move to an adjacent non-interior site at start of your move phase. Your bombers at a related system you control may move to this site. Bombers must return to system at end of your battle phase (if possible)."},{"id":"Dark:308","name":"•Bossk","type":"Character","text":"Adds 2 to power of anything he pilots. When piloting Hound's Tooth, draws one battle destiny if not able to otherwise. Adds 1 to attrition against opponent in battles at same site. While present, may reduce Chewie's forfeit to zero while here."},{"id":"Dark:312","name":"•Bossk's Mortar Gun","type":"Weapon","text":"Use 2 Force to deploy on Bossk, 4 on any other warrior. May fire using 2 Force. Draw destiny. If destiny > 0, one card with that destiny number at same site is lost (your choice). If destiny = 0, mortar gun explodes and warrior firing it is lost."},{"id":"Dark:336","name":"•Broken Concentration","type":"Effect","text":"Deploy on your side of table. Apprentices subtract X from training destiny, where X = ability - Jedi Test number (minimum zero). Also, once per turn, you may use 2 Force to move the top card of opponent's Force Pile to the top of opponent's Reserve Deck."},{"id":"Dark:366","name":"•Captain Needa","type":"Character","text":"Adds 2 to power of anything he pilots. When piloting Avenger, that starship is also immune to attrition < 4. You may re-target applicable Utinni Effects to Needa. While Needa in battle, your other non-'hit' characters here may not be forfeited."},{"id":"Dark:421","name":"•Close Call","type":"Interrupt","text":"USED: Cancel one asteroid destiny and cause it to be drawn again. LOST: Lose 1 Force. Opponent must reveal the top card of Reserve Deck, Force Pile and Used Pile. Card(s) with lowest destiny number greater than zero are lost."},{"id":"Dark:490","name":"•••Comm Chief","type":"Character","text":"Adds 2 to power of anything he pilots, and that starship or vehicle moves for free."},{"id":"Dark:491","name":"•Commander Brandei","type":"Character","text":"Adds 2 to power of anything he pilots. Once during each of your control phases, when aboard a Star Destroyer or at any docking bay, may use 1 Force to take one TIE into hand from Reserve Deck; reshuffle."},{"id":"Dark:495","name":"•Commander Gherant","type":"Character","text":"If aboard Executor (even at an Executor site), once during each of your deploy phases, may use 2 Force to search your Reserve Deck and take any one Executor site into hand. Shuffle, cut and replace."},{"id":"Dark:501","name":"•Commander Nemet","type":"Character","text":"Adds 1 to power and maneuver of anything he pilots. Opponent may not 'react' to or from same location."},{"id":"Dark:520","name":"Control","type":"Interrupt","text":"Cancel one Sense or Alter card. (Immune to Sense.) OR Cancel one Immediate Effect, Mobile Effect or Force drain."},{"id":"Dark:538","name":"•Corporal Derdram","type":"Character","text":"Power +1 when at any Executor site. While at Detention Block Corridor, cancels game text of Detention Block Control Room. May use 1 Force to search your Reserve Deck and take one IT-O or Hypo into hand. Shuffle, cut and replace."},{"id":"Dark:551","name":"•Corporal Vandolay","type":"Character","text":"May use 1 Force to search your Reserve Deck and take one Spice Mines Of Kessel or Detention Block Corridor into hand. Shuffle, cut and replace. While at a mobile site, We Have A Prisoner is a Used Interrupt."},{"id":"Dark:554","name":"<>Corrosive Damage","type":"Effect","text":"Deploy on Space Slug Belly. At the end of each player's turn, for every character and starship that player has present, that player must lose 1 Force. Effect canceled if Space Slug lost."},{"id":"Dark:599","name":"•Dagobah: Cave","type":"Location","text":"Dark: If opponent has presence here, your Force Icons are canceled. Light: Lose 1 Force during each of your control phases if Yoda on table but not on Dagobah."},{"id":"Dark:688","name":"•Defensive Fire","type":"Interrupt","text":"Cancel Rogue Asteroid, OR Randomly select one card from opponent's hand and place it, unseen, in Used Pile."},{"id":"Dark:700","name":"•Dengar","type":"Character","text":"Adds 2 to power of anything he pilots. Power +1 for each opponent's character present. While present, may reduce Han's forfeit to zero."},{"id":"Dark:704","name":"•Dengar's Blaster Carbine","type":"Weapon","text":"Use 1 Force to deploy on Dengar, 3 on your other warrior. May target a character, creature or vehicle using 1 Force. Draw destiny. Target hit if destiny +1 > defense value. If hit by Dengar, target's forfeit = 0."},{"id":"Dark:771","name":"<>Dragonsnake","type":"Creature","text":"Ferocity = 3 + destiny. Habitat: swamps, jungles and Dark Waters. May attack droids. Defeated droids are relocated to an adjacent exterior site (opponent of victim chooses)."},{"id":"Dark:906","name":"•Executor","type":"Starship","text":"May add unlimited pilots, passengers, vehicles and starfighters. Has ship-docking capability. Permanent pilots aboard provide total ability of 3. Immune to attrition < 12."},{"id":"Dark:907","name":"•Executor: Comm Station","type":"Location","text":"Dark: If you occupy with Tarkin, Piett or any admiral, your starships may 'react' to same system. Light: If you control, your starships may 'react' from same system as Executor."},{"id":"Dark:908","name":"•Executor: Control Station","type":"Location","text":"Dark: If an Imperial leader here, Executor is power +1 for each Executor site on table. Light: If you control, only you may move Executor during opponent's move phase."},{"id":"Dark:910","name":"•Executor: Holotheatre","type":"Location","text":"Dark: If you have Vader or Emperor on table, your Force generation is +1 here (+2 if both). Light: If you control, Force drain +1 here."},{"id":"Dark:911","name":"•Executor: Main Corridor","type":"Location","text":"Dark: During your move phase, you may move free between here and Executor or any Executor site. Light: If you control, opponent's Main Corridor game text is canceled."},{"id":"Dark:912","name":"•Executor: Meditation Chamber","type":"Location","text":"Dark: If Vader alone here, once per turn, may apply his ability to draw battle destiny at any system. Light: If you occupy, opponent's Meditation Chamber game text is canceled."},{"id":"Dark:918","name":"•Failure At The Cave","type":"Effect","text":"Deploy on Dagobah: Cave. Target an apprentice on Dagobah. All Jedi Test game text is suspended. If target present during any battle phase, opponent draws destiny. If destiny < 4, you retrieve 2 Force (also, if destiny = 0, target is lost). Otherwise, Utinni Effect canceled."},{"id":"Dark:929","name":"•Fear","type":"Interrupt","text":"Opponent must choose to lose either 2 Force from hand or 1 Force from top of Reserve Deck."},{"id":"Dark:937","name":"Field Promotion","type":"Effect","text":"Deploy on an Imperial of ability < 5 present with Vader, Emperor or one of your admirals, generals, or moffs. Imperial gains {leader} skill, is power +1, and is immune to Demotion, Report to Lord Vader, and What is Thy Bidding, My Master? (Immune to Alter.)"},{"id":"Dark:951","name":"•Flagship","type":"Effect","text":"Use 2 Force to deploy on your Star Destroyer. Your other starships may move as a 'react' to same system or sector (for free). If starship lost, you lose X Force, where X = starship's armor. (Immune to your Alter.)"},{"id":"Dark:991","name":"•Frustration","type":"Interrupt","text":"During your control phase, peek at opponent's hand and target one non-Interrupt card you find there that has a deploy cost < total number of [Light Side] icons on table. Opponent must deploy a card of that title by the end of your next turn, or lose a card of that title from hand (if possible)."},{"id":"Dark:1115","name":"•He Is Not Ready","type":"Effect","text":"Deploy on any character. Subtracts 2 from that character's training destiny draws. OR Deploy on an opponent's pilot at a site. During each of opponent's move phases, opponent must choose to move that character, lose that character or lose 1 Force."},{"id":"Dark:1150","name":"••HoloNet Transmission","type":"Interrupt","text":"USED: Cancel Transmission Terminated. LOST: Take one Imperial or Visage Of The Emperor into hand from Used Pile; reshuffle."},{"id":"Dark:1185","name":"•Hound's Tooth","type":"Starship","text":"May add 1 pilot (must be smuggler or bounty hunter), 6 passengers and 1 vehicle. Immune to attrition < 4 if Bossk piloting. Deploys and moves like a starfighter. Has ship-docking capability."},{"id":"Dark:1221","name":"•I Want That Ship","type":"Effect","text":"Deploy on one opponent's unique (•) starship at a location you do not occupy. When starship is targeted by any tractor beam or ion cannon, subtract 2 from maneuver. If starship is captured or lost, lose Effect and opponent must lose 3 Force (5 if Falcon)."},{"id":"Dark:1244","name":"•IG-2000","type":"Starship","text":"May add 1 pilot (must be a smuggler or bounty hunter) and 2 passengers. Maneuver +3 and immune to attrition < 3 if IG-88 piloting. Ion Cannon may deploy aboard."},{"id":"Dark:1245","name":"•IG-88","type":"Character","text":"Adds 2 to power of anything he pilots. May 'assassinate' any character at same site hit by IG-88 (victim is immediately lost). May use two different weapons. May initiate battle and be battled. Immune to Restraining Bolt and purchase."},{"id":"Dark:1249","name":"•IG-88's Neural Inhibitor","type":"Weapon","text":"Deploy on IG-88, or use 2 Force on any other bounty hunter. May target a non-droid character using 3 Force. Draw destiny. If destiny +1 > ability, until end of your next turn character is power, forfeit and landspeed = 0."},{"id":"Dark:1251","name":"•IG-88's Pulse Cannon","type":"Weapon","text":"Use 1 Force to deploy on IG-88, 4 on your other warrior. Adds 2 to power. May target X non-droid characters or creatures using X Force. Draw destiny for each. If destiny = 0, character is power -1 and forfeit -1 until end of turn. If destiny -1 > defense value, target hit."},{"id":"Dark:1255","name":"•Imbalance","type":"Interrupt","text":"If opponent just retrieved Force, opponent must lose X Force, where X = one-half the number of cards retrieved (round up)."},{"id":"Dark:1273","name":"•••Imperial Helmsman","type":"Character","text":"Adds 2 to power of anything he pilots. When piloting a Star Destroyer, also draws one battle destiny if not able to otherwise."},{"id":"Dark:1450","name":"•Knowledge And Defense","type":"Effect","text":"Insert in opponent's Reserve Deck. When Effect reaches top it is lost, but opponent may not initiate any battles for remainder of turn. (Immune to Alter.)"},{"id":"Dark:1470","name":"Lando System?","type":"Interrupt","text":"During your control phase, use 1 Force to move any one of your [Dagobah] icon characters of ability > 1 to any [Cloud City] icon location where you have presence. If moving to a Cloud City site, this movement is free and you do not need presence."},{"id":"Dark:1524","name":"•Lieutenant Commander Ardan","type":"Character","text":"If at a site, draws one battle destiny if not able to otherwise. Immune to attrition < X, where X = the number of opponent's aliens present."},{"id":"Dark:1538","name":"•Lieutenant Suba","type":"Character","text":"While at a Death Star or Executor site, your troopers deploy free there and are power and forfeit +1 there, and you may use 1 Force to search your Reserve Deck and take one Tactical Support into hand. Shuffle, cut and replace."},{"id":"Dark:1542","name":"•Lieutenant Venka","type":"Character","text":"Power +2 when at an Executor site or same site as Tarkin or Chief Bast, or if the Death Star has been 'blown away.' Fear Will Keep Them In Line is destiny +2 and, when it adds 1 to your power, also adds 1 to attrition against opponent."},{"id":"Dark:1569","name":"•Location, Location, Location","type":"Effect","text":"Deploy on table. At the end of each player's deploy phase, if they did not deploy a location, they lose 1 Force. Effect canceled if any player deploys three or more locations in a single turn."},{"id":"Dark:1583","name":"Lost In Space","type":"Effect","text":"If a pilot was just lost from a system or sector, deploy on that location and stack pilot here. Pilot may be rescued or captured by any capital starship present here during any move phase, and may be targeted by weapons (except during battle) as if present (treat as a starfighter with defense value = 0). Lost if no pilot here."},{"id":"Dark:1682","name":"•Mist Hunter","type":"Starship","text":"May add 2 pilots (one must be a smuggler or bounty hunter) and 3 passengers. Immune to attrition < 3 if Zuckuss is piloting. Has ship-docking capability."},{"id":"Dark:1710","name":"•Much Anger In Him","type":"Effect","text":"Deploy on a Rebel. At the end of each opponent's battle phases, if you have presence at the location where that Rebel has presences and a battle did not take place there, opponent loses 4 Force."},{"id":"Dark:1718","name":"Mynock","type":"Creature","text":"Habitat: unlimited. Parasite: Starfighter. Host's power and hyperspeed are cumulatively -2; while both < 1, Mynocks randomly detach one at a time (cannot attach for remainder of turn). Moves like a starfighter."},{"id":"Dark:1934","name":"Precision Targeting","type":"Effect","text":"Use 3 Force to deploy on table. Any card which is 'hit' may not be used to satisfy attrition. (Immune to Alter.)"},{"id":"Dark:1961","name":"Proton Bombs","type":"Weapon","text":"Deploy on a bomber: When present during a Force drain, may target a related interior site. Draw destiny. Site 'collapsed' if destiny > 4. OR May fire in a Bombing Run battle. Draw destiny. All characters, starships and vehicles with that destiny number at same site are lost."},{"id":"Dark:1967","name":"•Punishing One","type":"Starship","text":"May add 1 pilot (must be a smuggler or bounty hunter) and 1 passenger. Immune to attrition < 3 if Dengar piloting. Deploy -3 when deploying with Dengar. Boosted TIE Cannon may deploy aboard."},{"id":"Dark:2013","name":"•Raithal","type":"Location","text":"Dark: All your troopers are destiny +1 (+2 if you control). Tactical support is used interrupt. Light: If you occupy, opponent's Raithal game text is canceled."},{"id":"Dark:2091","name":"•Res Luk Ra'auf","type":"Interrupt","text":"If any bounty hunter is defending a battle alone, add one battle destiny. OR If Bossk, Greedo or Boba Fett is defending a battle alone, add two battle destiny."},{"id":"Dark:2123","name":"<>Rogue Asteroid","type":"Effect","text":"Deploy on an asteroid sector and specify starting direction. Every move phase, moves to next adjacent asteroid sector (reversing direction as necessary). Where present, adds 2 to asteroid destiny. May be targeted by starship weapons (defense value = 3)."},{"id":"Dark:2261","name":"•Shot In The Dark","type":"Effect","text":"Deploy on your side of table. Once per turn, you may lose 1 Force to draw the top card of your Reserve Deck into your hand. If that card is a space creature, you may immediately deploy it for free."},{"id":"Dark:2262","name":"•Shut Him Up Or Shut Him Down","type":"Interrupt","text":"Cancel Death Star Plans, The Professor, Bacta Tank, How Did We Get Into This Mess?, Shoo! Shoo! or Thank The Maker."},{"id":"Dark:2281","name":"Sleen","type":"Creature","text":"Ferocity = destiny - 3. Habitat: planet sites (except Hoth and Tatooine) and Dark Waters. Cumulatively absorbs (temporarily cancels) one [Light Side Force] icon present. Parasite: None."},{"id":"Dark:2302","name":"Something Hit Us!","type":"Interrupt","text":"During a battle, lose 1 Force. Cumulatively adds 1 to attrition against opponent."},{"id":"Dark:2312","name":"<>Space Slug","type":"Creature","text":"* Ferocity = two destiny. Habitat: Big One (Cave is now Belly). Attacks starfighters (defeated cards are eaten or relocated to Belly, opponent of victim chooses). Once per turn, may open or close mouth."},{"id":"Dark:2343","name":"•••Star Destroyer: Launch Bay","type":"Location","text":"Dark: Your TIEs deploy -2 here. You may shuttle, transfer, embark and disembark here for free. Light: Starships captured by Star Destroyer go here and may be Besieged. Immune to Revolution."},{"id":"Dark:2369","name":"Sudden Impact","type":"Effect","text":"Deploy on any Effect or Utinni Effect (except those immune to Alter). During each of owner's draw phases, if you occupy an asteroid sector, owner must choose to either lose 1 Force or voluntarily cancel that Effect or Utinni Effect. (Immune to Alter.)"},{"id":"Dark:2401","name":"•Take Evasive Action","type":"Interrupt","text":"Cancel Egregious Pilot Error, Out Of Nowhere, Collision! or Don't Get Cocky. OR Use 1 Force to subtract 3 from all asteroid destiny draws against you for remainder of turn."},{"id":"Dark:2518","name":"The Dark Path","type":"Effect","text":"Deploy on your side of table. Once per turn, you may peek at the top three cards of your Reserve Deck. Place any two of those three in your Lost Pile."},{"id":"Dark:2551","name":"•There Is No Try","type":"Effect","text":"Deploy on table. Sense and Alter are now Lost Interrupts. Also, when any player makes a destiny draw for Sense or Alter, and that destiny draw is successful, that player loses 2 Force. (Immune to Alter.)"},{"id":"Dark:2580","name":"Those Rebels Won't Escape Us","type":"Interrupt","text":"USED: Cancel Nabrun Leids. LOST: During your move phase, cancel Landing Claw. OR Cancel Hyper Escape, Closer?! or one 'react.'"},{"id":"Dark:2597","name":"TIE Avenger","type":"Starship","text":"Deploy -1 to same system as any Imperial capital starship. May add 1 pilot. Boosted TIE Cannon may deploy aboard."},{"id":"Dark:2598","name":"TIE Bomber","type":"Starship","text":"Power +2 during a Bombing Run battle. Permanent pilot aboard provides ability of 1. At any time during your turn, may use 1 Force to 'diffuse' (lose or return to hand) any one Orbital Mine present."},{"id":"Dark:2669","name":"Uncertain Is The Future","type":"Interrupt","text":"Use 3 Force. Each player places hand onto Reserve Deck (if possible), then places Used Pile onto Reserve Deck; reshuffle. Each player then draws cards from Reserve Deck equal to the number of cards just placed from hand onto Reserve Deck (if any)."},{"id":"Dark:2677","name":"•Unexpected Interruption","type":"Interrupt","text":"Use 2 Force to search your Reserve Deck and take one Interrupt into hand. Shuffle, cut and replace."},{"id":"Dark:2717","name":"Vine Snake","type":"Creature","text":"Habitat: planet sites (except Hoth). Attacks a character by attaching. X starts at 0. Every move phase, draw destiny; each time destiny > ability, add 1 to X. Character is power -X (eaten if power = 0)."},{"id":"Dark:2721","name":"•Visage Of The Emperor","type":"Effect","text":"Lose 2 Force to deploy on Executor: Holotheatre or Death Star: Conference Room. At the end of each player's turn, each player must lost 1 Force. Effect canceled if opponent controls this site. (Immune to Alter.)"},{"id":"Dark:2728","name":"••Voyeur","type":"Interrupt","text":"Name an Interrupt card. Opponent must reveal entire Used Pile, without shuffling. Then you choose:USED: Opponent must lose 1 Force for each copy of that Interrupt found there. LOST: Each copy of that interrupt found there is lost."},{"id":"Dark:2739","name":"•Warrant Officer M'Kae","type":"Character","text":"Adds 2 to power of anything he pilots. May use 1 Force to take one tractor beam, Our First Catch Of The Day or Besieged into hand from Reserve Deck; reshuffle."},{"id":"Dark:2912","name":"•Zuckuss","type":"Character","text":"Adds 2 to power of anything he pilots. May move for free as a 'react.' Once during each battle, may use 1 Force to cause one alien of ability < 3 at same site to be forfeit = 0 for remainder of turn. Immune to attrition < 3."},{"id":"Dark:2915","name":"•Zuckuss' Snare Rifle","type":"Weapon","text":"Deploy on Zuckuss, or use 1 Force to deploy on any other bounty hunter. May target a character or creature using 2 Force. Draw destiny. Character captured if destiny -1 > defense value. Creature lost if destiny +1 > defense value."}],devices={"Light:155":["starfighter",0,true],"Light:780":["r-unit",0,false],"Light:1108":["character-or-craft",1,false],"Light:1464":["starfighter",0,false],"Light:1602":["character",0,true],"Light:1926":["warrior",0,true],"Light:2037":["pilot-character",0,false],"Light:2104":["r-unit",0,true]},counters={"Light:424":["rogue asteroid","close call"],"Light:521":["sense","alter"],"Dark:520":["sense","alter"],"Light:814":["limited resources"],"Light:1512":["silence is golden","shut him up or shut him down"],"Light:1550":["dark maneuvers","emergency deployment","lone pilot","i want that ship","defensive fire","rogue asteroid","take evasive action"],"Light:2344":["awwww, cannot get your ship out"],"Light:2574":["corrosive damage"],"Light:2573":["this is just wrong"],"Light:2752":["res luk ra'auf"],"Light:2629":["hologram"],"Dark:688":["rogue asteroid"],"Dark:1150":["transmission terminated"],"Dark:2262":["death star plans","the professor","bacta tank","how did we get into this mess?","shoo! shoo!","thank the maker"],"Dark:2401":["egregious pilot error","out of nowhere","collision!","don't get cocky"],"Dark:2580":["nabrun leids","hyper escape","closer?!"]};
 const definitions=cards.map(card=>{const event=/^Jedi Test/.test(card.type)?'dagobahJediTest':'dagobah'+card.type.replace(/ /g,'');const effects=[{event,summary:card.text,since:32}];if(devices[card.id]){const [targets,cost,allowOpponent]=devices[card.id];effects.push({event:'device',targets,cost,allowOpponent,summary:'Device am passenden Träger ausspielen; Aktionen erscheinen bei der Karte.',since:32});}if(counters[card.id])effects.push({event:'namedCancellation',names:counters[card.id],summary:'Genannte Karte regelgerecht aufheben.',since:32});return {id:card.id,effects,complete:true};});
 PremiereCardRules.registerExpansion(definitions);
 return Object.freeze({definitions,cards});
})();
